const student = $('Get student').first().json;
const courses = $('Get Courses').all().map(item => item.json);
const assessments = $('Get Assessments').all().map(item => item.json);

const results = [];

for (const course of courses) {

  const courseAssessments = assessments.filter(
    a => String(a.course_id) === String(course.course_id)
  );

  let weightedContribution = 0;
  let completedWeight = 0;
  let remainingWeight = 0;

  for (const assessment of courseAssessments) {

    const weight = Number(assessment.weight || 0);
    const grade = assessment.grade;

    if (grade !== undefined && grade !== null && grade !== '') {

      weightedContribution += Number(grade) * (weight / 100);
      completedWeight += weight;

    } else {

      remainingWeight += weight;

    }
  }

  const currentAverage =
    completedWeight > 0
      ? (weightedContribution / completedWeight) * 100
      : 0;

  results.push({
  student_id: student.student_id,
  weekly_study_hours: Number(student.weekly_study_hours),
  course_id: course.course_id,
    course_name: course.course_name,
    target_grade: Number(course.target_grade),

    current_average: Number(currentAverage.toFixed(2)),

    weighted_contribution: Number(
      weightedContribution.toFixed(2)
    ),

    completed_weight: completedWeight,

    remaining_weight: remainingWeight,

    assessments: courseAssessments
  });
}

return results.map(result => ({
  json: result
}));

const planner = $('Planner Agent').first().json.output;
const studentId = planner.student_id;
const generatedAt = new Date().toISOString();

const rows = [];
for (const item of (planner.study_plan || [])) {
  rows.push({
    student_id: studentId,
    date: item.date,
    course_id: item.course_id,
    course_name: item.course_name,
    task: item.task,
    hours: item.hours,
    priority: item.priority,
    generated_at: generatedAt
  });
}

return rows.map(r => ({ json: r }));

const extracted = $json.output;

/* The extractor's schema calls these assessment_name / deadline, but the
   website's data contract (README.md, sample-data.js) is name / weight /
   due_date. Normalise here, or the syllabus review screen shows every row
   with a blank name and blank date and refuses to save. */
const assessments = (extracted.assessments || []).map(a => ({
  name:     a.name || a.assessment_name || '',
  weight:   (a.weight === null || a.weight === undefined) ? null : Number(a.weight),
  due_date: a.due_date || a.deadline || '',
}));

let totalWeight = 0;
let hasMissingWeights = false;

for (const assessment of assessments) {
  if (assessment.weight === null || assessment.weight === undefined) {
    hasMissingWeights = true;
  } else {
    totalWeight += Number(assessment.weight);
  }
}

const weightsValid = !hasMissingWeights && totalWeight === 100;

return [
  {
    json: {
      course_name: extracted.course_name,
      course_code: extracted.course_code,
      assessments: assessments,

      total_weight: totalWeight,
      has_missing_weights: hasMissingWeights,
      weights_valid: weightsValid,

      requires_confirmation: true
    }
  }
];

