const state    = $('Calculate Academic State').all().map(i => i.json);
const analysis = $('Academic Analyst Agent').first().json.output || {};
const plan     = $('Format Study Plan').all().map(i => i.json);

const today = new Date().toISOString().slice(0, 10);
const DAY = 86400000;
const t0 = new Date(today).getTime();

const courses = state.map(s => {
  const a = (analysis.courses || []).find(c => String(c.course_id) === String(s.course_id)) || {};

  /* A course with nothing graded yet cannot be assessed. Without this the
     agent still invents a risk level for it, and Number(null) turns a
     missing average into 0, so a brand new course reads as "0%, CRITICAL".
     Decide it here rather than trusting the model. */
  const hasGrades = (Number(s.completed_weight) || 0) > 0;

  const earned    = Number(s.weighted_contribution) || 0;
  const remaining = Number(s.remaining_weight) || 0;
  const target    = Number(s.target_grade) || 80;

  const maxAchievable  = Math.min(100, earned + remaining);
  const neededTarget   = remaining > 0 ? Number((((target - earned) / remaining) * 100).toFixed(2)) : null;
  const neededPass     = remaining > 0 ? Number((((60 - earned) / remaining) * 100).toFixed(2)) : null;

  const assessments = (s.assessments || []).map(x => {
    const raw = x.grade;
    const graded = raw !== '' && raw !== null && raw !== undefined;
    const due = x.deadline || x.due_date || '';
    let days = null;
    if (due) {
      const d = new Date(due).getTime();
      if (!isNaN(d)) days = Math.round((d - t0) / DAY);
    }
    return {
      assessment_id: x.assessment_id,
      name: x.assessment_name || x.name || 'Assessment',
      weight: Number(x.weight) || 0,
      grade: graded ? Number(raw) : null,
      due_date: due,
      days_until_due: days,
      status: graded ? 'Completed' : 'Upcoming',
    };
  });

  const next = assessments
    .filter(x => x.status !== 'Completed' && x.days_until_due !== null && x.days_until_due >= 0)
    .sort((p, q) => p.days_until_due - q.days_until_due)[0];

  return {
    course_id: String(s.course_id),
    course_code: s.course_code || '',
    course_name: s.course_name,
    target_grade: target,
    current_average: hasGrades ? Number(s.current_average) : null,
    points_earned_so_far: earned,
    completed_weight: Number(s.completed_weight) || 0,
    remaining_weight: remaining,
    max_achievable_grade: Number(maxAchievable.toFixed(2)),
    needed_avg_on_remaining_for_target: neededTarget,
    needed_avg_on_remaining_to_pass: neededPass,
    target_reachable: remaining > 0 ? neededTarget <= 100 : earned >= target,
    pass_reachable:   remaining > 0 ? neededPass   <= 100 : earned >= 60,
    risk_level: hasGrades ? (a.risk_level || 'MEDIUM') : 'NOT_ANALYZED',
    priority: hasGrades ? (a.priority || 99) : null,
    recommended_weekly_hours: hasGrades ? (a.recommended_weekly_hours || 0) : 0,
    next_deadline_in_days: next ? next.days_until_due : null,
    reason: hasGrades
      ? (a.reason || '')
      : 'No grades have been recorded yet, so this course has not been analysed. Add a grade and it will be assessed.',
    focus: hasGrades ? (a.focus || []) : [],
    assessments: assessments,
  };
});

return [{ json: {
  success: true,
  student_id: analysis.student_id || (state[0] && state[0].student_id) || '',
  /* If nothing at all is graded, the student is not "at risk" - there is
     simply nothing to judge yet. */
  overall_status: courses.some(c => c.risk_level !== 'NOT_ANALYZED')
    ? (analysis.overall_status || 'AT_RISK')
    : 'NOT_ANALYZED',
  available_weekly_study_hours: Number(state[0] && state[0].weekly_study_hours) || 15,
  today: today,
  courses: courses,
  study_plan: plan,
}}];

/* Risk Alert filter
   Keeps only HIGH / CRITICAL courses from the Academic Analyst Agent and
   attaches the student's name + email, which "Get student" already read from
   the Students sheet at the start of this execution.

   Returning [] stops the branch, so no email is sent when nothing is at risk.
   We deliberately do NOT add a second Google Sheets read here: a Sheets node
   placed after a multi-item node runs once per item and returns the whole tab
   each time (HANDOFF trap 8). */

const analysis = $input.first().json.output || {};
const courses  = (analysis.courses || []).filter(
  c => c.risk_level === 'HIGH' || c.risk_level === 'CRITICAL'
);

if (!courses.length) return [];

const student = $('Get student').first().json || {};
const email   = String(student.email || '').trim();

if (!email) return [];

return courses
  .sort((a, b) => (a.priority || 99) - (b.priority || 99))
  .map(c => ({
    json: {
      student_id:    analysis.student_id || student.student_id || '',
      student_name:  student.name || 'there',
      student_email: email,
      course_name:   c.course_name || 'your course',
      risk_level:    c.risk_level,
      reason:        c.reason || 'No reason was returned by the analyst.',
      recommended_weekly_hours: c.recommended_weekly_hours ?? 0,
      focus: Array.isArray(c.focus) ? c.focus.join(', ') : String(c.focus || ''),
    },
  }));
